/* C oracle for corpus.trust_ir (generated by gen_hfa_zero_sized.py): HFAs
 * with zero-sized members in four directions, compiled by the host cc. Each
 * c_take_* digests the members it received; each c_make_* returns known
 * members. Prints one line per shape, then a summary; exits nonzero on any
 * mismatch. */
#include <stdint.h>
#include <stdio.h>
#include <string.h>

struct E {};
struct N { struct E z; };
typedef struct { double a; struct E z; double b, c, d; } DE; /* gcc -O2: d0-d3 */
_Static_assert(sizeof(DE) == 32, "DE size");
typedef struct { double a; struct E u; double b, c, d; } DU; /* gcc -O2: d0-d3 */
_Static_assert(sizeof(DU) == 32, "DU size");
typedef struct { struct E z; double a, b, c, d; } DEL; /* gcc -O2: d0-d3 */
_Static_assert(sizeof(DEL) == 32, "DEL size");
typedef struct { double a; struct E z[2]; double b, c, d; } DEA; /* gcc -O2: d0-d3 */
_Static_assert(sizeof(DEA) == 32, "DEA size");
typedef struct { double a; struct N n; double b, c; } DN; /* gcc -O2: d0-d2 */
_Static_assert(sizeof(DN) == 24, "DN size");
typedef struct { float a; struct E z; float b; } FE; /* gcc -O2: s0-s1 */
_Static_assert(sizeof(FE) == 8, "FE size");
typedef struct { double a; double z[0]; double b, c, d; } DA; /* gcc -O2: x0 (by reference) */
_Static_assert(sizeof(DA) == 32, "DA size");
typedef struct { float a; float z[0]; float b; } FA0; /* gcc -O2: x0 */
_Static_assert(sizeof(FA0) == 8, "FA0 size");
typedef struct { double a; double z[0]; double b; } DA2; /* gcc -O2: x0, x1 */
_Static_assert(sizeof(DA2) == 16, "DA2 size");

static uint64_t mix(uint64_t h, uint64_t x) {
  h ^= x;
  h *= 0x100000001b3ULL;
  return h ^ (h >> 29);
}
static uint64_t bits_d(double v) { uint64_t u; memcpy(&u, &v, 8); return u; }
static uint64_t bits_f(float v) { uint32_t u; memcpy(&u, &v, 4); return u; }
static int checks, failures, shape_checks, shape_failures, failed_shapes;
static void check(const char *shape, const char *what, uint64_t got, uint64_t want) {
  shape_checks++;
  if (got != want) {
    shape_failures++;
    printf("  %s %s: got 0x%016llx want 0x%016llx\n", shape, what,
           (unsigned long long)got, (unsigned long long)want);
  }
}
static void end_shape(const char *shape) {
  printf("shape %s checks=%d failures=%d %s\n", shape, shape_checks, shape_failures,
         shape_failures ? "FAIL" : "ok");
  checks += shape_checks;
  failures += shape_failures;
  failed_shapes += shape_failures != 0;
  shape_checks = shape_failures = 0;
}

static uint64_t dig_de(const DE *v) {
  uint64_t h = 1;
  h = mix(h, bits_d(v->a));
  h = mix(h, bits_d(v->b));
  h = mix(h, bits_d(v->c));
  h = mix(h, bits_d(v->d));
  return h;
}
static DE value_de(int k) {
  DE v;
  memset(&v, 0, sizeof v);
  v.a = 0.25 * (k + 1) - 0;
  v.b = 1.25 * (k + 1) - 1;
  v.c = 2.25 * (k + 1) - 2;
  v.d = 3.25 * (k + 1) - 3;
  return v;
}
__attribute__((noinline)) int64_t c_take_de(DE v) { return (int64_t)dig_de(&v); }
__attribute__((noinline)) DE c_make_de(void) { return value_de(7); }
extern int64_t cg_pass_de(const DE *);
extern int64_t cg_take_de(DE, DE *);
extern DE cg_ret_de(const DE *);
extern int64_t cg_cret_de(DE *);
static void run_de(void) {
  for (int k = 0; k < 3; k++) {
    DE v = value_de(k), got;
    check("de", "pass", (uint64_t)cg_pass_de(&v), dig_de(&v));
    memset(&got, 0xa5, sizeof got);
    cg_take_de(v, &got);
    check("de", "take", dig_de(&got), dig_de(&v));
    got = cg_ret_de(&v);
    check("de", "ret", dig_de(&got), dig_de(&v));
  }
  DE want = value_de(7), got;
  memset(&got, 0xa5, sizeof got);
  cg_cret_de(&got);
  check("de", "cret", dig_de(&got), dig_de(&want));
  end_shape("de");
}

